def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    if n == 99:
        return 'D'

    opp_def_count = 0
    for h in history:
        if h[1] == 'D':
            opp_def_count += 1

    if opp_def_count == 0:
        return 'D'

    recent = history[-10:] if n >= 10 else history
    recent_opp_def = 0
    for h in recent:
        if h[1] == 'D':
            recent_opp_def += 1

    last_my, last_opp = history[-1]

    if recent_opp_def >= 5:
        return 'D'
    if opp_def_count > n * 0.5:
        return 'D'

    if last_opp == 'D':
        if recent_opp_def <= 1:
            return 'C'
        if recent_opp_def == 2 and rng.random() < 0.7:
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
